          speakText("Yes, Boss? I am online and listening.");

          setTimeout(() => {
            setWakeWordDetected(false);
            setWakeStatus("idle");
          }, 4000);
        }
      }
    };

    rec.onerror = (err: any) => {
      console.warn("[Wake Word Engine Exception]:", err.error || err);
      if (err.error === "aborted") return;
      if (err.error === "no-speech") {
        setWakeInterimText("");
