// Helper to list all source files in the codebase recursively
async function getFilesList(dir: string): Promise<string[]> {
  const dirents = await fs.readdir(dir, { withFileTypes: true });
  const files = await Promise.all(
    dirents.map((dirent) => {
      const res = path.resolve(dir, dirent.name);
      const relPath = path.relative(process.cwd(), res);

      if (
        dirent.name === "node_modules" ||
        dirent.name === "dist" ||
        dirent.name === ".git" ||
        dirent.name === ".cache" ||
        dirent.name === "server.cjs" ||
        dirent.name === "server.cjs.map" ||
        dirent.name === "package-lock.json"
      ) {
        return [];
      }

      return dirent.isDirectory() ? getFilesList(res) : [relPath];
    })
  );
  return files.flat();
}

// Safe path resolver
function safeResolvePath(filePath: string): string {
  const resolved = path.resolve(process.cwd(), filePath);
  if (!resolved.startsWith(process.cwd())) {
    throw new Error("Directory traversal blocked: access restricted to project workspace.");
  }
  return resolved;
}

// Lazy initialization of Gemini API to check key presence safely.
let googleGenAI: GoogleGenAI | null = null;
function getGeminiClient(): GoogleGenAI {
  if (!googleGenAI) {
    const key = process.env.GEMINI_API_KEY;
    if (!key) {
      throw new Error("GEMINI_API_KEY environment variable is missing. Configure it in Secrets to enable active cognitive AI endpoints.");
    }
    googleGenAI = new GoogleGenAI({
      apiKey: key,
      httpOptions: {
        headers: {
          "User-Agent": "aistudio-build",
        },
      },
    });
  }
  return googleGenAI;
}

// robust helper to perform content generation, catching and falling back to alternative stable models if overloaded
async function generateContentWithFallback(
  ai: GoogleGenAI,
  options: { contents: any; config?: any }
) {
  const modelsToTry = ["gemini-3.5-flash", "gemini-3.1-flash-lite", "gemini-flash-latest"];
  let lastError: any = null;

  for (const model of modelsToTry) {
    const maxRetries = 2;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        return await ai.models.generateContent({
          model,
          contents: options.contents,
          config: options.config,
        });
      } catch (err: any) {
        lastError = err;
        const errStr = (err.message || "").toLowerCase();

        // Quota / Rate limit exhaustion errors
        const isQuotaExhausted = 
          err.status === "RESOURCE_EXHAUSTED" || 
          errStr.includes("429") || 
          errStr.includes("quota exceeded") || 
          errStr.includes("rate limit") ||
          errStr.includes("limit exceeded") ||
          errStr.includes("exhausted");

        if (isQuotaExhausted) {
          console.log(`[Gemini API Info] Quota resource check for '${model}'. Trying next stable option...`);
          break; // Break the attempt loop for this model and go back to outer loop to try next model
        }

        const isTransient = 
          err.status === "UNAVAILABLE" || 
          errStr.includes("503") || 
          errStr.includes("high demand") || 
          errStr.includes("temporary");

        if (isTransient && attempt < maxRetries) {
          const delay = (attempt + 1) * 800;
          console.log(`[Gemini API Info] Connection check for '${model}' (Attempt ${attempt + 1}/${maxRetries + 1}). Retrying connection...`);
          await new Promise(resolve => setTimeout(resolve, delay));
        } else {
          console.log(`[Gemini API Info] Standby check for '${model}'. Routing query to fallback pipeline...`);
          break; // break the retry loop, try the next model
        }
      }
    }
  }

  console.error("[Gemini API Info] Fallback sequence completed: Routing error handler.");
  throw lastError;
}

