async function runTelegramPollingLoop() {
  if (telegramLoopRunning) {
    console.log("[Telegram Protocol] Redundant runTelegramPollingLoop blocked: Loop is already running.");
    return;
  }

  telegramLoopRunning = true;

  try {
    while (telegramPollingActive) {
      if (!telegramBotToken) {
        telegramPollingActive = false;
        break;
      }

      // Check if this token's webhook needs resetting
      if (telegramBotToken !== telegramLastClearedToken) {
        const currentToken = telegramBotToken;
        try {
          console.log("[Telegram Protocol] Resetting active webhook status for token on Telegram API server...");
          const clearUrl = `https://api.telegram.org/bot${currentToken}/deleteWebhook?drop_pending_updates=true`;
          const res = await fetch(clearUrl);
          const data = await res.json() as any;
          console.log("[Telegram Protocol] Webhook deletion result for token:", data);
          telegramLastClearedToken = currentToken;
        } catch (err: any) {
          console.warn("[Telegram Protocol] Webhook delete warning for token:", err.message || err);
        }
      }

      try {
        const url = `https://api.telegram.org/bot${telegramBotToken}/getUpdates?offset=${lastUpdateId}&timeout=10`;
        const response = await fetch(url);

        if (!response.ok) {
          if (response.status === 401 || response.status === 404) {
            console.error(`[Telegram Protocol] Authorization failed (${response.status}). Standing down loop.`);
            telegramPollingActive = false;
            break;
          }
          if (response.status === 409) {
            console.warn(`[Telegram Protocol] Conflict (status 409). A webhook is active on this bot, or another instance is polling. Standing down polling loop to avoid interference.`);
            telegramPollingActive = false;
            break;
          }
          throw new Error(`Integration endpoint returned status ${response.status}`);
        }

        const data = await response.json() as any;
        if (data.ok && data.result && data.result.length > 0) {
          for (const update of data.result) {
            lastUpdateId = Math.max(lastUpdateId, update.update_id + 1);

            if (update.message && update.message.text) {
              const chatId = update.message.chat.id;
              const text = update.message.text;
              const firstName = update.message.chat.first_name || "Boss";

              console.log(`[Telegram Bot uplink] Received update from ${firstName}: "${text}"`);

              // Execute the universal cogent matrix
              const formattedMessage = `[Telegram Chat from ${firstName}]: ${text}`;

              const currentHistory = await loadChatHistory();
              const trimmedHistory = currentHistory.slice(-8);

              // Trigger the brain!
              const agentFeedback = await runJarvisAgent(formattedMessage, trimmedHistory, null, "telegram", chatId);

              // Direct message dispatch back to client Telegram
              const sendUrl = `https://api.telegram.org/bot${telegramBotToken}/sendMessage`;
              await fetch(sendUrl, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  chat_id: chatId,
