  "recommendations": ["Array of direct instructions on how to patch these defects, styled for the Boss user"]
}
`;
        const responseText = await generateContentWithFallback(aiClient, {
          contents: payloadPrompt,
          config: { responseMimeType: "application/json" }
        });

        const synthData = JSON.parse(responseText.text || "{}");
        overviewText = synthData.overview || `Completed active monitoring on ${cleanDomain}.`;
        postureGrade = synthData.postureGrade || "B";
        if (Array.isArray(synthData.techStack)) matchedStack = synthData.techStack;
        if (Array.isArray(synthData.vulnerabilities)) vulnerabilitiesFound = synthData.vulnerabilities;
        if (Array.isArray(synthData.recommendations)) tacticalRecommendations = synthData.recommendations;

      } catch (err: any) {
        console.error("[Web Intelligence] AI Synthesis generated a parse exception, using fallback metrics:", err.message);
        overviewText = `Static telemetry completed for domain ${cleanDomain}. SSL active certificate is pointing to ${sslInfo?.issuer?.O || "Unknown Issuer"}.`;
        postureGrade = headerSecurityScore > 50 ? "B" : "C-";
        vulnerabilitiesFound = missingSecurityHeaders.map(h => `Header security risk: missing ${h.toUpperCase()} response header leaves consumers vulnerable.`);
        tacticalRecommendations = missingSecurityHeaders.map(h => `Configure your server middleware to immediately inject '${h}' response security headers.`);
      }
    } else {
      overviewText = `Telemetry probe completed successfully for domain host '${cleanDomain}'. SSL socket handshake evaluated and verified. Node is resolving IP caches under live networking.`;
      postureGrade = headerSecurityScore >= 80 ? "A" : headerSecurityScore >= 50 ? "B-" : headerSecurityScore >= 30 ? "C" : "D";

      if (missingSecurityHeaders.includes("content-security-policy")) {
